final class Cache {
  private val lock = new Object
  private val entries = scala.collection.mutable.Map.empty[String, Entry]

  def find(key: String): Entry = lock.synchronized {
    entries.getOrElseUpdate(key, insertImpl(key))   // monitor held (reentrant)
  }

  private def insertImpl(key: String): Entry = Entry(key)  // assumes held
}
